WITH promo_active AS ( SELECT p.p_promo_id, p.p_item_sk, p.p_start_date_sk, p.p_end_date_sk, p.p_cost, p.p_discount_active, start_dim.d_date AS start_date, end_dim.d_date AS end_date FROM promotion p JOIN date_dim start_dim ON p.p_start_date_sk = start_dim.d_date_sk JOIN date_dim end_dim ON p.p_end_date_sk = end_dim.d_date_sk WHERE p.p_discount_active = 'Y' ) SELECT d.d_fy_year, i.i_class, COUNT(*) AS returns_cnt, SUM(sr.sr_net_loss) AS total_net_loss, AVG(sr.sr_net_loss) AS avg_net_loss, SUM(COALESCE(pa.p_cost, 0)) AS total_promo_cost, RANK() OVER (PARTITION BY d.d_fy_year ORDER BY AVG(sr.sr_net_loss) DESC) AS class_rank FROM store_returns sr JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN item i ON sr.sr_item_sk = i.i_item_sk LEFT JOIN promo_active pa ON sr.sr_item_sk = pa.p_item_sk AND sr.sr_returned_date_sk BETWEEN pa.p_start_date_sk AND pa.p_end_date_sk WHERE d.d_holiday = 'N' AND i.i_category = 'Electronics' GROUP BY d.d_fy_year, i.i_class ORDER BY d.d_fy_year, avg_net_loss DESC
